int x(int arr[], int n)
{
	int ans = 0;
	for (int i = 0; i < n - 1; i++)
	{
		int m = i;
		for (int j = i + 1; j < n; j++)
		{
			if (arr[j] < arr[m])
				m = j;
		}
		if (m != i)
		{
			int temp = arr[i];
			arr[i] = arr[m];
			arr[m] = temp;
			ans++;
		}
	}
	return ans;
}
int main()
{
	int arr[] = {64, 25, 12, 22, 11, 90, 34};
	cout << x(arr, 7) << endl;
	for(int i = 0; i < 7; i++)
		cout << arr[i] << " ";
	return 0;
}
